using DeviceTelemetry.Domain.Common;

namespace DeviceTelemetry.Domain.Entities;

/// <summary>A single telemetry message accepted from a device.</summary>
public class TelemetryEvent : BaseAuditableEntity
{
    /// <summary>Time-ordered GUID (v7) generated by the application, so it is known before the row is saved.</summary>
    public Guid Id { get; set; }

    public int DeviceId { get; set; }
    public Device Device { get; set; } = null!;

    public int StatusCode { get; set; }

    /// <summary>When the event happened according to the device; falls back to <see cref="ReceivedAtUtc"/>.</summary>
    public DateTime OccurredAtUtc { get; set; }

    /// <summary>When the server accepted the message.</summary>
    public DateTime ReceivedAtUtc { get; set; }

    /// <summary>Optional device-supplied structured data, stored as <c>jsonb</c>.</summary>
    public string? Payload { get; set; }

    /// <summary>Device-generated message identifier used for de-duplication; unique per device.</summary>
    public Guid? MessageId { get; set; }

    /// <summary>
    /// SHA-256 of the idempotency-relevant request content, set only together with <see cref="MessageId"/>.
    /// Lets a retry with the same <see cref="MessageId"/> but different content be detected.
    /// </summary>
    public byte[]? ContentHash { get; set; }
}
